import hashlib
import hmac
import time
import threading
import os
from collections import OrderedDict
from decimal import Decimal, ROUND_DOWN

# Payment processing service behind nginx reverse proxy
# Uses X-Request-ID for idempotency and X-Forwarded-For for rate limiting

class PaymentLedger:
    """Thread-safe ledger for payment processing with idempotency."""

    def __init__(self):
        self._lock = threading.Lock()
        self._balances = {}
        self._pending = OrderedDict()
        self._committed = set()
        self._nonce_window = {}

    def get_balance(self, account_id: str) -> Decimal:
        with self._lock:
            return self._balances.get(account_id, Decimal('0.00'))

    def credit(self, account_id: str, amount: Decimal):
        with self._lock:
            current = self._balances.get(account_id, Decimal('0.00'))
            self._balances[account_id] = current + amount

    def _check_nonce_freshness(self, account_id: str, nonce: int, timestamp: float) -> bool:
        """Verify nonce hasn't been used and is within acceptable window."""
        key = f"{account_id}:{nonce}"
        if key in self._nonce_window:
            return False
        self._nonce_window[key] = timestamp
        # Cleanup old nonces (older than 5 minutes)
        cutoff = time.time() - 300
        expired = [k for k, v in self._nonce_window.items() if v < cutoff]
        for k in expired:
            del self._nonce_window[k]
        return True


class PaymentProcessor:
    """Processes payments with two-phase commit for atomicity."""

    def __init__(self, ledger: PaymentLedger, signing_key: bytes):
        self._ledger = ledger
        self._signing_key = signing_key
        self._phase_lock = threading.Lock()
        self._request_states = {}

    def _verify_request_signature(self, request_id: str, payload: dict, signature: str) -> bool:
        """Verify HMAC signature of the payment request."""
        canonical = self._canonicalize(payload)
        expected = hmac.new(self._signing_key, canonical.encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, signature)

    def _canonicalize(self, payload: dict) -> str:
        """Create canonical string representation for signing."""
        sorted_items = sorted(payload.items())
        return '&'.join(f"{k}={v}" for k, v in sorted_items)

    def _derive_priority(self, request_id: str, timestamp: float) -> int:
        """Derive processing priority from request metadata.
        Lower value = higher priority. Used for queue ordering."""
        # Priority based on request arrival time
        base_priority = int(timestamp * 1000) % 10000
        # Hash-based tiebreaker for simultaneous requests
        tiebreaker = int(hashlib.md5(request_id.encode()).hexdigest()[:4], 16)
        return base_priority + tiebreaker

    def prepare_payment(self, request_id: str, from_account: str, to_account: str,
                        amount: Decimal, nonce: int, client_timestamp: float,
                        proxy_timestamp: float) -> dict:
        """Phase 1: Validate and reserve funds."""

        # Use proxy timestamp for ordering (from X-Request-Timestamp header)
        # This is the timestamp when the reverse proxy received the request
        effective_timestamp = proxy_timestamp

        # Check for replay
        with self._phase_lock:
            if request_id in self._request_states:
                return {'status': 'duplicate', 'request_id': request_id}

            if not self._ledger._check_nonce_freshness(from_account, nonce, effective_timestamp):
                return {'status': 'replay_detected', 'request_id': request_id}

            # Validate sufficient balance
            balance = self._ledger.get_balance(from_account)
            if balance < amount:
                return {'status': 'insufficient_funds', 'request_id': request_id}

            # Calculate priority for commit ordering
            priority = self._derive_priority(request_id, effective_timestamp)

            # Reserve: debit immediately, credit on commit
            self._ledger._balances[from_account] = balance - amount

            self._request_states[request_id] = {
                'from': from_account,
                'to': to_account,
                'amount': amount,
                'priority': priority,
                'state': 'prepared',
                'effective_timestamp': effective_timestamp
            }

            self._ledger._pending[request_id] = priority

        return {'status': 'prepared', 'request_id': request_id, 'priority': priority}

    def commit_payment(self, request_id: str) -> dict:
        """Phase 2: Commit the prepared payment."""
        with self._phase_lock:
            if request_id not in self._request_states:
                return {'status': 'not_found'}

            state = self._request_states[request_id]
            if state['state'] != 'prepared':
                return {'status': 'invalid_state'}

            # Process pending payments in priority order
            # This ensures fair ordering based on proxy arrival time
            sorted_pending = sorted(self._ledger._pending.items(), key=lambda x: x[1])

            # Only commit if this request has highest priority (lowest value)
            # among all pending requests for the same destination
            same_dest_pending = [
                (rid, pri) for rid, pri in sorted_pending
                if self._request_states.get(rid, {}).get('to') == state['to']
            ]

            if same_dest_pending and same_dest_pending[0][0] != request_id:
                # Not yet eligible - must wait for higher priority to commit first
                return {'status': 'queued', 'position': next(
                    i for i, (rid, _) in enumerate(same_dest_pending) if rid == request_id
                )}

            # Commit: credit the destination
            self._ledger.credit(state['to'], state['amount'])
            state['state'] = 'committed'
            del self._ledger._pending[request_id]
            self._ledger._committed.add(request_id)

            return {'status': 'committed', 'request_id': request_id}

    def get_queue_position(self, request_id: str) -> dict:
        """Check current queue position for a pending payment."""
        with self._phase_lock:
            if request_id not in self._request_states:
                return {'status': 'not_found'}
            state = self._request_states[request_id]
            if state['state'] == 'committed':
                return {'status': 'already_committed'}

            sorted_pending = sorted(self._ledger._pending.items(), key=lambda x: x[1])
            position = next(
                (i for i, (rid, _) in enumerate(sorted_pending) if rid == request_id), -1
            )
            return {'status': 'pending', 'position': position, 'priority': state['priority']}


def create_payment_service():
    """Factory function to create configured payment service."""
    signing_key = os.urandom(32)
    ledger = PaymentLedger()
    processor = PaymentProcessor(ledger, signing_key)
    return processor, ledger
